-- Continue Çanakkale catalogue with major archaeological and museum destinations.
insert into public.places (name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,external_id,verified,trust_score,is_active,content_review_status,tags)
select v.name,v.category,v.place_type,'Çanakkale',v.address,v.lat,v.lon,v.slug,v.short_desc,v.long_desc,v.src,'curated_seed',v.ext,false,85,true,'source_backed',to_jsonb(v.tags)
from (values
('Troya Ören Yeri','Tarih ve arkeoloji','Örenyeri','Tevfikiye, Merkez, Çanakkale',39.9575,26.2389,'troya-oren-yeri','UNESCO Dünya Mirası Listesi’ndeki antik Troya yerleşimi','Troya, farklı dönemlere ait yerleşim katmanlarıyla Anadolu ve Ege tarihinin en önemli arkeolojik alanlarından biridir.','https://canakkale.ktb.gov.tr/TR-70509/muze-ve-oren-yerleri.html','canakkale-troya-oren-yeri',array['arkeoloji','unesco','antik kent']::text[]),
('Troya Müzesi','Müze','Arkeoloji müzesi','Tevfikiye, Merkez, Çanakkale',39.9565,26.2375,'troya-muzesi','Troya ve çevresindeki arkeolojik alanlardan eserler','Troya Müzesi, Troya ve Troas bölgesinin arkeolojik mirasını eserler ve sergileme alanları üzerinden tanıtır.','https://kvmgm.ktb.gov.tr/TR-44078/canakkale-muze-mudurlugu.html','canakkale-troya-muzesi',array['müze','arkeoloji','troas']::text[]),
('Neandria Antik Kenti','Tarih ve arkeoloji','Antik kent','Kayacık, Ezine, Çanakkale',39.75,26.80,'neandria-antik-kenti','Antik Troas bölgesindeki kent kalıntıları','Neandria, Çanakkale’nin antik Troas coğrafyasındaki önemli yerleşimlerinden biridir; arazi koşulları ve erişim durumu önceden araştırılmalıdır.','https://canakkale.gov.tr/kultur-ve-turizm','canakkale-neandria-antik-kenti',array['arkeoloji','antik kent','troas']::text[]),
('Sestos Antik Kenti','Tarih ve arkeoloji','Antik kent','Akbaş çevresi, Eceabat, Çanakkale',40.25,26.35,'sestos-antik-kenti','Çanakkale Boğazı’nın Avrupa yakasındaki antik yerleşim','Sestos, boğaz geçişi ve antik kaynaklardaki yeriyle bilinen tarihî Troas yerleşimlerindendir. Kalıntıların ziyaret edilebilirliği önceden teyit edilmelidir.','https://canakkale.gov.tr/kultur-ve-turizm','canakkale-sestos-antik-kenti',array['arkeoloji','antik kent','tarih']::text[]),
('Dardanos Tümülüsü','Tarih ve arkeoloji','Tümülüs','Dardanos, Çanakkale Merkez',40.08,26.35,'dardanos-tumulusu','Bölgenin antik mezar geleneğini yansıtan arkeolojik alan','Dardanos Tümülüsü, Çanakkale çevresindeki arkeolojik mirasın parçalarındandır; erişim ve ziyaret koşulları ilgili kurumdan doğrulanmalıdır.','https://canakkale.gov.tr/kultur-ve-turizm','canakkale-dardanos-tumulusu',array['arkeoloji','tümülüs','tarih']::text[])
) as v(name,category,place_type,address,lat,lon,slug,short_desc,long_desc,src,ext,tags)
where not exists (select 1 from public.places p where p.city='Çanakkale' and (p.slug=v.slug or p.external_id=v.ext or p.name=v.name));